import type { ReactNode } from "react";
import Button from "@mui/material/Button";
import type { AuthCopy } from "../copy";
import { providerIcon } from "./ProviderIcons";

type SocialProvider = {
    alias: string;
    displayName: string;
    loginUrl: string;
    iconClasses?: string;
    providerId?: string;
};

/**
 * Renders only the identity providers the realm actually exposes. The URLs are
 * generated by Keycloak, so the OAuth/OIDC handshake always goes through the
 * configured broker endpoint.
 */
export function SocialProviders(props: { providers: SocialProvider[]; copy: AuthCopy }): ReactNode {
    const { providers, copy } = props;

    if (providers.length === 0) {
        return null;
    }

    return (
        <div className="sz-social">
            <div className="sz-divider" role="separator" aria-label={copy.orContinueWith}>
                <span>{copy.orContinueWith}</span>
            </div>
            <div className="sz-social-list">
                {providers.map(provider => (
                    <Button
                        key={provider.alias}
                        id={`social-${provider.alias}`}
                        component="a"
                        href={provider.loginUrl}
                        variant="outlined"
                        fullWidth
                        className="sz-social-button"
                        startIcon={providerIcon(provider.alias, provider.providerId)}
                    >
                        {copy.continueWith(provider.displayName)}
                    </Button>
                ))}
            </div>
        </div>
    );
}
